input.command:
cd ~/development/stallion && gh label create stage --color 1d76db --description "One stage of the build plan" 2>&1; gh label create needs-approval --color d93f0b --description "Needs approval before implementation" 2>&1
cat > ~/development/.tmp/stallion-issues/file.mjs <<'EOF'
import { readFileSync, writeFileSync } from "node:fs";
import { execFileSync } from "node:child_process";
const dir = `${process.env.HOME}/development/.tmp/stallion-issues`;
const titles = [
  "bootstrap the repo",
  "build the geometry core",
  "add the object schema and codec",
  "build the local-only drawing app",
  "sync tiles through a rust durable object",
  "persist tiles and flush them on an alarm",
  "add the bounded view query",
  "add client sync",
  "wire sync into the drawing app",
  "support cross-tile edits",
  "check the access jwt on the websocket upgrade",
  "deploy with free-tier guardrails",
];
const approval = new Set([4, 5, 6, 11]);
const nums = {};
for (let i = 0; i < titles.length; i++) {
  const id = String(i).padStart(2, "0");
  const body = readFileSync(`${dir}/${id}.md`, "utf8").replace(/\{\{(\d+)\}\}/g, (_, n) => {
    if (!(n in nums)) throw new Error(`stage ${i} refs unfiled ${n}`);
    return nums[n];
  });
  const bodyFile = `${dir}/${id}.final.md`;
  writeFileSync(bodyFile, body);
  const labels = approval.has(i) ? "stage,needs-approval" : "stage";
  const url = execFileSync("gh", ["issue", "create", "--repo", "mvhenten/stallion", "--title", `${id}: ${titles[i]}`, "--body-file", bodyFile, "--label", labels], { encoding: "utf8" }).trim();
  nums[i] = url.split("/").pop();
  console.log(`${id} #${nums[i]} ${url}`);
}
EOF
node ~/development/.tmp/stallion-issues/file.mjs

